/* ============================================
   GlobalStone — Global Commercial Real Estate
   Design System & Shared Styles
   ============================================ */

/* ── Google Fonts ── */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Playfair+Display:wght@500;600;700&display=swap');

/* ── CSS Variables ── */
:root {
  /* Brand colors from source_brief.md */
  --primary: #003F2D;
  --primary-dark: #012A2D;
  --accent: #C9A96E;
  --accent-hover: #B8975E;
  --neutral: #E6E6E6;
  --neutral-light: #F5F5F5;
  --neutral-dark: #6B7280;
  --text-primary: #111827;
  --text-secondary: #4B5563;
  --text-muted: #9CA3AF;
  --white: #FFFFFF;
  --black: #000000;

  /* Semantic */
  --background: var(--white);
  --foreground: var(--text-primary);
  --surface: var(--neutral-light);
  --surface-elevated: var(--white);
  --border: #E5E7EB;

  /* Typography */
  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-serif: 'Playfair Display', Georgia, serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', monospace;

  /* Spacing scale (4px base) */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
  --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);

  /* Border radius */
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease-out;

  /* Layout */
  --header-height: 72px;
  --container-max: 1280px;
  --container-narrow: 1024px;
}

/* ── Reset & Base ── */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  color: var(--foreground);
  background: var(--background);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

ul, ol {
  list-style: none;
}

/* ── Typography ── */
.heading-1 {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 600;
  line-height: 1.15;
  letter-spacing: -0.02em;
  color: var(--text-primary);
}

.heading-2 {
  font-family: var(--font-serif);
  font-size: clamp(1.5rem, 3.5vw, 2.5rem);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.01em;
  color: var(--text-primary);
}

.heading-3 {
  font-family: var(--font-sans);
  font-size: clamp(1.125rem, 2vw, 1.5rem);
  font-weight: 600;
  line-height: 1.3;
  color: var(--text-primary);
}

.heading-4 {
  font-family: var(--font-sans);
  font-size: 1.125rem;
  font-weight: 600;
  line-height: 1.4;
  color: var(--text-primary);
}

.body-large {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--text-secondary);
}

.body-small {
  font-size: 0.875rem;
  line-height: 1.6;
  color: var(--text-secondary);
}

.label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
}

/* ── Layout Utilities ── */
.container {
  width: 100%;
  max-width: var(--container-max);
  margin: 0 auto;
  padding-left: var(--space-6);
  padding-right: var(--space-6);
}

.container-narrow {
  max-width: var(--container-narrow);
}

.section {
  padding-top: var(--space-20);
  padding-bottom: var(--space-20);
}

.section-sm {
  padding-top: var(--space-12);
  padding-bottom: var(--space-12);
}

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  border-radius: var(--radius-sm);
  transition: all var(--transition-fast);
  cursor: pointer;
  min-height: 44px;
}

.btn-primary {
  background: var(--accent);
  color: var(--white);
}

.btn-primary:hover {
  background: var(--accent-hover);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background: var(--primary);
  color: var(--white);
}

.btn-secondary:hover {
  background: var(--primary-dark);
  transform: translateY(-1px);
}

.btn-outline {
  background: transparent;
  color: var(--text-primary);
  border: 1.5px solid var(--border);
}

.btn-outline:hover {
  border-color: var(--text-primary);
  background: var(--surface);
}

.btn-ghost {
  background: transparent;
  color: var(--white);
  border: 1.5px solid rgba(255,255,255,0.4);
}

.btn-ghost:hover {
  background: rgba(255,255,255,0.1);
  border-color: rgba(255,255,255,0.6);
}

.btn-link {
  padding: 0;
  background: none;
  color: var(--primary);
  font-weight: 600;
  font-size: 0.875rem;
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
}

.btn-link:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}

.btn-link::after {
  content: '→';
  transition: transform var(--transition-fast);
}

.btn-link:hover::after {
  transform: translateX(3px);
}

/* ── Cards ── */
.card {
  background: var(--surface-elevated);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.card-image {
  width: 100%;
  aspect-ratio: 16 / 10;
  object-fit: cover;
}

.card-body {
  padding: var(--space-6);
}

/* ── Header & Navigation ── */
.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  height: var(--header-height);
  background: var(--white);
  border-bottom: 1px solid var(--border);
  transition: box-shadow var(--transition-base);
}

.site-header.scrolled {
  box-shadow: var(--shadow-md);
}

.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
  letter-spacing: -0.02em;
}

.logo span {
  color: var(--accent);
}

/* Desktop nav */
.desktop-nav {
  display: none;
}

@media (min-width: 1024px) {
  .desktop-nav {
    display: flex;
    align-items: center;
    gap: var(--space-8);
  }
}

.nav-link {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--text-secondary);
  padding: var(--space-2) 0;
  position: relative;
  transition: color var(--transition-fast);
}

.nav-link:hover,
.nav-link.active {
  color: var(--text-primary);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--accent);
  transition: width var(--transition-base);
}

.nav-link:hover::after,
.nav-link.active::after {
  width: 100%;
}

/* Services mega menu trigger */
.nav-services-trigger {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  cursor: pointer;
}

.nav-services-trigger svg {
  width: 16px;
  height: 16px;
  transition: transform var(--transition-fast);
}

.nav-services-trigger[aria-expanded="true"] svg {
  transform: rotate(180deg);
}

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: var(--header-height);
  left: 0;
  right: 0;
  background: var(--white);
  border-bottom: 1px solid var(--border);
  box-shadow: var(--shadow-xl);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: all var(--transition-base);
  z-index: 999;
}

.mega-menu.open {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-menu-inner {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: var(--space-12);
  padding: var(--space-10) var(--space-6);
  max-width: var(--container-max);
  margin: 0 auto;
}

.mega-menu-section h4 {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: var(--space-4);
}

.mega-menu-links {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-3);
}

.mega-menu-links a {
  display: block;
  padding: var(--space-2) 0;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.mega-menu-links a:hover {
  color: var(--primary);
}

.mega-menu-property-types {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
}

.mega-menu-property-types a {
  display: block;
  padding: var(--space-2) 0;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color var(--transition-fast);
}

.mega-menu-property-types a:hover {
  color: var(--primary);
}

/* Mobile menu toggle */
.mobile-menu-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  color: var(--text-primary);
}

@media (min-width: 1024px) {
  .mobile-menu-toggle {
    display: none;
  }
}

/* Mobile Navigation */
.mobile-nav {
  position: fixed;
  inset: 0;
  background: var(--white);
  z-index: 1001;
  padding: var(--space-6);
  padding-top: calc(var(--header-height) + var(--space-6));
  transform: translateX(100%);
  transition: transform var(--transition-slow);
  overflow-y: auto;
}

.mobile-nav.open {
  transform: translateX(0);
}

.mobile-nav-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--header-height);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 var(--space-6);
  background: var(--white);
  border-bottom: 1px solid var(--border);
  z-index: 1002;
}

.mobile-nav-close {
  width: 44px;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-primary);
}

.mobile-nav-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.mobile-nav-item {
  border-bottom: 1px solid var(--border);
}

.mobile-nav-link {
  display: block;
  padding: var(--space-4) 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--text-primary);
}

.mobile-accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: var(--space-4) 0;
  font-size: 1.125rem;
  font-weight: 500;
  color: var(--text-primary);
  background: none;
  border: none;
  cursor: pointer;
}

.mobile-accordion-header svg {
  width: 20px;
  height: 20px;
  transition: transform var(--transition-fast);
  color: var(--text-muted);
}

.mobile-accordion-header[aria-expanded="true"] svg {
  transform: rotate(180deg);
}

.mobile-accordion-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-base);
}

.mobile-accordion-panel.open {
  max-height: 500px;
}

.mobile-accordion-panel a {
  display: block;
  padding: var(--space-3) 0 var(--space-3) var(--space-4);
  font-size: 1rem;
  color: var(--text-secondary);
  border-left: 2px solid var(--border);
  margin-left: var(--space-2);
}

.mobile-accordion-panel a:hover {
  color: var(--primary);
  border-left-color: var(--accent);
}

/* ── Hero ── */
.hero {
  position: relative;
  min-height: 70vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}

.hero-bg img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to bottom,
    rgba(1, 42, 45, 0.75) 0%,
    rgba(1, 42, 45, 0.55) 50%,
    rgba(1, 42, 45, 0.8) 100%
  );
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  text-align: center;
  max-width: 800px;
  padding: var(--space-8);
}

.hero-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent);
  margin-bottom: var(--space-4);
}

.hero-title {
  font-family: var(--font-serif);
  font-size: clamp(2rem, 5vw, 3.75rem);
  font-weight: 600;
  line-height: 1.1;
  color: var(--white);
  margin-bottom: var(--space-6);
  letter-spacing: -0.02em;
}

.hero-subtitle {
  font-size: 1.125rem;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.85);
  margin-bottom: var(--space-8);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

/* ── Section Headers ── */
.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto var(--space-12);
}

.section-header-left {
  text-align: left;
  margin-left: 0;
}

.section-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent);
  margin-bottom: var(--space-3);
}

.section-title {
  font-family: var(--font-serif);
  font-size: clamp(1.75rem, 3.5vw, 2.5rem);
  font-weight: 600;
  line-height: 1.2;
  color: var(--text-primary);
  margin-bottom: var(--space-4);
}

.section-desc {
  font-size: 1.0625rem;
  line-height: 1.7;
  color: var(--text-secondary);
}

/* ── Grids ── */
.grid-2 {
  display: grid;
  gap: var(--space-8);
}

@media (min-width: 768px) {
  .grid-2 {
    grid-template-columns: repeat(2, 1fr);
  }
}

.grid-3 {
  display: grid;
  gap: var(--space-8);
}

@media (min-width: 768px) {
  .grid-3 {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .grid-3 {
    grid-template-columns: repeat(3, 1fr);
  }
}

.grid-4 {
  display: grid;
  gap: var(--space-6);
}

@media (min-width: 640px) {
  .grid-4 {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .grid-4 {
    grid-template-columns: repeat(4, 1fr);
  }
}

/* ── Announcement Banner ── */
.announcement-banner {
  background: var(--primary);
  color: var(--white);
  padding: var(--space-4) 0;
}

.announcement-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-4);
  text-align: center;
}

@media (min-width: 768px) {
  .announcement-inner {
    flex-direction: row;
    justify-content: center;
    text-align: left;
  }
}

.announcement-text {
  font-size: 1rem;
  font-weight: 500;
}

/* ── Tabs ── */
.tabs-vertical {
  display: grid;
  gap: var(--space-8);
}

@media (min-width: 768px) {
  .tabs-vertical {
    grid-template-columns: 280px 1fr;
  }
}

.tab-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.tab-btn {
  text-align: left;
  padding: var(--space-4) var(--space-5);
  font-size: 1rem;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: var(--radius-md);
  border-left: 3px solid transparent;
  transition: all var(--transition-fast);
  background: none;
}

.tab-btn:hover {
  background: var(--surface);
  color: var(--text-primary);
}

.tab-btn.active {
  background: var(--surface);
  color: var(--primary);
  border-left-color: var(--accent);
  font-weight: 600;
}

.tab-panel {
  display: none;
  animation: fadeIn 300ms ease-out;
}

.tab-panel.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ── Footer ── */
.site-footer {
  background: var(--primary-dark);
  color: rgba(255, 255, 255, 0.7);
  padding-top: var(--space-16);
  padding-bottom: var(--space-8);
}

.footer-grid {
  display: grid;
  gap: var(--space-10);
  margin-bottom: var(--space-12);
}

@media (min-width: 768px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .footer-grid {
    grid-template-columns: 2fr 1fr 1fr 1fr;
  }
}

.footer-brand .logo {
  color: var(--white);
  margin-bottom: var(--space-4);
}

.footer-brand p {
  font-size: 0.9375rem;
  line-height: 1.7;
  max-width: 320px;
}

.footer-col h4 {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--white);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-5);
}

.footer-col a {
  display: block;
  font-size: 0.9375rem;
  padding: var(--space-2) 0;
  transition: color var(--transition-fast);
}

.footer-col a:hover {
  color: var(--white);
}

.footer-bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: var(--space-8);
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  align-items: center;
  text-align: center;
}

@media (min-width: 768px) {
  .footer-bottom {
    flex-direction: row;
    justify-content: space-between;
    text-align: left;
  }
}

.footer-legal {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-4);
  justify-content: center;
}

@media (min-width: 768px) {
  .footer-legal {
    justify-content: flex-start;
  }
}

.footer-legal a {
  font-size: 0.8125rem;
  transition: color var(--transition-fast);
}

.footer-legal a:hover {
  color: var(--white);
}

/* ── Utility ── */
.text-white { color: var(--white); }
.text-center { text-align: center; }
.bg-surface { background: var(--surface); }
.bg-primary { background: var(--primary); }
.bg-primary-dark { background: var(--primary-dark); }

/* ── Insight Cards ── */
.insight-card {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
}

.insight-card-image {
  border-radius: var(--radius-lg);
  overflow: hidden;
  aspect-ratio: 16 / 10;
}

.insight-card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform var(--transition-slow);
}

.insight-card:hover .insight-card-image img {
  transform: scale(1.03);
}

.insight-card-meta {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--accent);
}

.insight-card-title {
  font-size: 1.125rem;
  font-weight: 600;
  line-height: 1.4;
  color: var(--text-primary);
}

.insight-card-date {
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* ── Service Cards ── */
.service-card {
  background: var(--surface-elevated);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  transition: all var(--transition-base);
}

.service-card:hover {
  border-color: var(--accent);
  box-shadow: var(--shadow-lg);
  transform: translateY(-4px);
}

.service-card h3 {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: var(--space-3);
  color: var(--text-primary);
}

.service-card p {
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--text-secondary);
  margin-bottom: var(--space-5);
}

/* ── Commitment Cards ── */
.commitment-card {
  background: var(--surface-elevated);
  border-radius: var(--radius-lg);
  padding: var(--space-8);
  border: 1px solid var(--border);
  transition: all var(--transition-base);
}

.commitment-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--accent);
}

.commitment-card h3 {
  font-size: 1.125rem;
  font-weight: 600;
  margin-bottom: var(--space-3);
  color: var(--text-primary);
}

.commitment-card p {
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--text-secondary);
  margin-bottom: var(--space-4);
}

/* ── Carousel ── */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform var(--transition-slow);
}

.carousel-slide {
  flex: 0 0 100%;
  padding: var(--space-4);
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: var(--space-3);
  margin-top: var(--space-6);
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1.5px solid var(--border);
  background: var(--white);
  color: var(--text-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition-fast);
}

.carousel-btn:hover {
  background: var(--primary);
  color: var(--white);
  border-color: var(--primary);
}

.carousel-dots {
  display: flex;
  gap: var(--space-2);
  align-items: center;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border);
  transition: all var(--transition-fast);
  cursor: pointer;
  border: none;
}

.carousel-dot.active {
  background: var(--accent);
  width: 24px;
  border-radius: 4px;
}

/* ── Testimonial ── */
.testimonial {
  background: var(--surface);
  border-radius: var(--radius-xl);
  padding: var(--space-12);
  text-align: center;
  max-width: 800px;
  margin: 0 auto;
}

.testimonial-quote {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
  font-style: italic;
  line-height: 1.5;
  color: var(--text-primary);
  margin-bottom: var(--space-8);
}

.testimonial-author {
  font-weight: 600;
  color: var(--text-primary);
}

.testimonial-role {
  font-size: 0.875rem;
  color: var(--text-muted);
}

/* ── Scroll animations ── */
.reveal {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 500ms ease-out, transform 500ms ease-out;
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
  html {
    scroll-behavior: auto;
  }
}

/**
 * GlobalStone — Shared JavaScript
 * Navigation, tabs, carousel, scroll effects
 */

(function () {
  'use strict';

  /* ── Header scroll effect ── */
  const header = document.querySelector('.site-header');
  if (header) {
    window.addEventListener('scroll', () => {
      header.classList.toggle('scrolled', window.scrollY > 10);
    });
  }

  /* ── Mega Menu ── */
  const servicesTrigger = document.querySelector('.nav-services-trigger');
  const megaMenu = document.querySelector('.mega-menu');

  if (servicesTrigger && megaMenu) {
    let timeoutId;

    const openMega = () => {
      clearTimeout(timeoutId);
      servicesTrigger.setAttribute('aria-expanded', 'true');
      megaMenu.classList.add('open');
    };

    const closeMega = () => {
      timeoutId = setTimeout(() => {
        servicesTrigger.setAttribute('aria-expanded', 'false');
        megaMenu.classList.remove('open');
      }, 150);
    };

    servicesTrigger.addEventListener('mouseenter', openMega);
    servicesTrigger.addEventListener('focus', openMega);
    megaMenu.addEventListener('mouseenter', () => clearTimeout(timeoutId));

    servicesTrigger.addEventListener('mouseleave', closeMega);
    megaMenu.addEventListener('mouseleave', closeMega);

    // Click toggle for accessibility
    servicesTrigger.addEventListener('click', (e) => {
      e.preventDefault();
      const isOpen = megaMenu.classList.contains('open');
      if (isOpen) {
        closeMega();
      } else {
        openMega();
      }
    });

    // Close on Escape
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && megaMenu.classList.contains('open')) {
        closeMega();
        servicesTrigger.focus();
      }
    });
  }

  /* ── Mobile Navigation ── */
  const mobileToggle = document.querySelector('.mobile-menu-toggle');
  const mobileNav = document.querySelector('.mobile-nav');
  const mobileClose = document.querySelector('.mobile-nav-close');

  if (mobileToggle && mobileNav) {
    mobileToggle.addEventListener('click', () => {
      mobileNav.classList.add('open');
      document.body.style.overflow = 'hidden';
    });

    if (mobileClose) {
      mobileClose.addEventListener('click', () => {
        mobileNav.classList.remove('open');
        document.body.style.overflow = '';
      });
    }

    // Close mobile nav on link click
    mobileNav.querySelectorAll('a').forEach((link) => {
      link.addEventListener('click', () => {
        mobileNav.classList.remove('open');
        document.body.style.overflow = '';
      });
    });
  }

  /* ── Mobile Accordion ── */
  document.querySelectorAll('.mobile-accordion-header').forEach((header) => {
    header.addEventListener('click', () => {
      const panel = header.nextElementSibling;
      const isOpen = panel.classList.contains('open');

      // Close all others
      document.querySelectorAll('.mobile-accordion-panel').forEach((p) => {
        p.classList.remove('open');
        p.previousElementSibling.setAttribute('aria-expanded', 'false');
      });

      if (!isOpen) {
        panel.classList.add('open');
        header.setAttribute('aria-expanded', 'true');
      }
    });
  });

  /* ── Vertical Tabs ── */
  document.querySelectorAll('.tabs-vertical').forEach((tabsContainer) => {
    const tabBtns = tabsContainer.querySelectorAll('.tab-btn');
    const tabPanels = tabsContainer.querySelectorAll('.tab-panel');

    tabBtns.forEach((btn) => {
      btn.addEventListener('click', () => {
        const targetId = btn.getAttribute('data-tab');

        tabBtns.forEach((b) => b.classList.remove('active'));
        tabPanels.forEach((p) => p.classList.remove('active'));

        btn.classList.add('active');
        const targetPanel = tabsContainer.querySelector(`[data-panel="${targetId}"]`);
        if (targetPanel) targetPanel.classList.add('active');
      });
    });
  });

  /* ── Carousel ── */
  document.querySelectorAll('.carousel').forEach((carousel) => {
    const track = carousel.querySelector('.carousel-track');
    const slides = carousel.querySelectorAll('.carousel-slide');
    const prevBtn = carousel.querySelector('.carousel-prev');
    const nextBtn = carousel.querySelector('.carousel-next');
    const dots = carousel.querySelectorAll('.carousel-dot');

    if (!track || slides.length === 0) return;

    let current = 0;

    const goTo = (index) => {
      current = (index + slides.length) % slides.length;
      track.style.transform = `translateX(-${current * 100}%)`;

      dots.forEach((dot, i) => {
        dot.classList.toggle('active', i === current);
      });
    };

    if (prevBtn) prevBtn.addEventListener('click', () => goTo(current - 1));
    if (nextBtn) nextBtn.addEventListener('click', () => goTo(current + 1));

    dots.forEach((dot, i) => {
      dot.addEventListener('click', () => goTo(i));
    });

    // Auto-advance every 6s
    setInterval(() => goTo(current + 1), 6000);
  });

  /* ── Scroll reveal ── */
  const revealElements = document.querySelectorAll('.reveal');
  if (revealElements.length > 0) {
    const revealObserver = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            entry.target.classList.add('visible');
            revealObserver.unobserve(entry.target);
          }
        });
      },
      { threshold: 0.1, rootMargin: '0px 0px -40px 0px' }
    );

    revealElements.forEach((el) => revealObserver.observe(el));
  }

  /* ── Lucide icons ── */
  if (typeof lucide !== 'undefined') {
    lucide.createIcons();
  }
})();
